<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ArrowLeft, BookOpen, Compass, LayoutGrid, ShieldCheck } from '@lucide/vue'
import { authError, currentUser, initializeAuth, localMockAuth, register, signIn } from './auth'
import './portal.css'
const loading=ref(true)
const theme=(()=>{try{return localStorage.getItem('personal-portal-theme')||'system'}catch{return 'system'}})()
const travel=window.location.pathname.startsWith('/travel')
const appName=travel?'旅行规划':'个人空间'
function reconnect(){window.location.reload()}
onMounted(async()=>{await initializeAuth();loading.value=false})
</script>
<template><slot v-if="currentUser"/><main v-else class="personal-portal account-gate" :class="`portal-${theme}`"><header><a href="/"><ArrowLeft :size="16"/>返回门户</a><span><LayoutGrid :size="16"/>我的空间</span></header><div class="gate-layout"><section class="gate-intro"><span class="gate-eyebrow">YOUR PERSONAL SPACE</span><h1>旅行的灵感，<br/>生活的每一笔。</h1><p>一个账号，安放你的行程与日常。<br/>登录后继续使用{{ appName }}。</p><div class="gate-apps"><span><Compass :size="19"/>旅行规划</span><span><BookOpen :size="19"/>日常记账</span></div></section><section class="gate-card"><span class="gate-icon"><ShieldCheck :size="25"/></span><small>欢迎回来</small><h2>{{ loading?'正在准备个人空间':`登录后打开${appName}` }}</h2><p>你的地点、行程和账本，各自妥善保存。</p><button v-if="!loading" type="button" class="gate-primary" @click="localMockAuth?reconnect():signIn()">{{ localMockAuth?'重新连接本地服务':'登录并继续 →' }}</button><button v-if="!loading&&!localMockAuth" type="button" class="gate-secondary" @click="register()">还没有账号？创建账号</button><p v-if="authError" role="alert" class="gate-error">{{ authError }}</p><footer>只是逛逛？<a href="/">返回门户首页</a></footer></section></div></main></template>
