{.gate-layout{grid-template-columns:1fr;gap:30px;max-width:460px;padding-top:40px;align-content:center}.gate-intro h1{font-size:30px;margin:15px 0}.gate-intro p{font-size:12px}.gate-apps{display:none}.gate-card{padding:30px}.gate-intro{text-align:center}.gate-intro h1>br{display:none}}@media(max-width:480px){.account-gate{padding:22px}.gate-layout{padding:30px 0}.gate-intro h1{font-size:26px}.gate-card{padding:26px 24px;border-radius:22px}.gate-card h2{font-size:22px}}
